const monthName = (value = '') => {
  const parsed = new Date(`${value}-01T00:00:00`);
  return Number.isNaN(parsed.getTime()) ? value : new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(parsed);
};
