function EmptyState({ icon: Icon, title, body, action }: { icon: typeof Wallet; title: string; body: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card/60 p-12 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon className="h-5 w-5" /></div><h3 className="mt-4 display-font text-xl font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{body}</p>{action && <div className="mt-5">{action}</div>}</div>;
}
function PageTitle({ eyebrow, title, body, action }: { eyebrow: string; title: string; body: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="mono-font text-xs uppercase tracking-[.18em] text-primary">{eyebrow}</p><h1 className="display-font mt-2 text-4xl font-bold tracking-tight">{title}</h1><p className="mt-2 max-w-2xl text-muted-foreground">{body}</p></div>{action}</div>;
}
function StatCard({ label, value, detail, tone = 'default', icon: Icon }: { label: string; value: string; detail: string; tone?: 'default' | 'dark' | 'accent'; icon: typeof Wallet }) {
  return <div className={`rounded-2xl border p-5 ${tone === 'dark' ? 'border-sidebar bg-sidebar text-sidebar-foreground' : tone === 'accent' ? 'border-accent bg-accent/45 text-accent-foreground' : 'border-border bg-card'}`}><div className="flex items-center justify-between"><span className={`text-sm ${tone === 'dark' ? 'text-sidebar-foreground/60' : 'text-muted-foreground'}`}>{label}</span><Icon className={`h-4 w-4 ${tone === 'dark' ? 'text-sidebar-primary' : 'text-primary'}`} /></div><p className="mono-font mt-5 text-2xl font-medium tracking-tight">{value}</p><p className={`mt-2 text-xs ${tone === 'dark' ? 'text-sidebar-foreground/60' : 'text-muted-foreground'}`}>{detail}</p></div>;
}

