function Protected({ children }: { children: ReactNode }) {
  const { isLoaded, isSignedIn } = useAuth();
  if (!isLoaded) return <div className="min-h-[100dvh] bg-background p-8"><LoadingState label="Opening your money space..." /></div>;
  if (!isSignedIn) return <Redirect to="/sign-in" />;
  return <AppShell>{children}</AppShell>;
}

function DashboardPage() {
  const dashboard = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const user = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey() } });
  if (dashboard.isLoading || user.isLoading) return <LoadingState />;
  if (dashboard.isError) return <ErrorState retry={() => dashboard.refetch()} />;
  const data = dashboard.data;
  if (!data) return null;
  const displayName = user.data?.name?.split(' ')[0] ?? 'there';
  return <div className="animate-rise-in"><PageTitle eyebrow="Thursday, October 24" title={`Good afternoon, ${displayName}.`} body="Here’s your money at a glance. You’re doing better than you think." action={<Link href="/transactions" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground hover:-translate-y-0.5" data-testid="link-add-transaction"><Plus className="h-4 w-4" /> Add transaction</Link>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><StatCard label="Available balance" value={formatMoney(data.balance)} detail={`${data.savingsRate.toFixed(1)}% savings rate`} icon={Wallet} tone="dark" /><StatCard label="Income this month" value={formatMoney(data.totalIncome)} detail="Across all sources" icon={ArrowDownLeft} /><StatCard label="Spent this month" value={formatMoney(data.monthlyExpenses)} detail={`${data.highestCategory} is your top category`} icon={ArrowUpRight} tone="accent" /><StatCard label="Left in budgets" value={formatMoney(data.budgetRemaining)} detail="Room for the rest of the month" icon={Target} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-sm text-muted-foreground">Spending snapshot</p><h2 className="display-font mt-1 text-2xl font-bold">{formatMoney(data.monthlyExpenses)} <span className="text-sm font-normal text-muted-foreground">this month</span></h2></div><Link href="/analytics" className="text-sm font-semibold text-primary" data-testid="link-view-analytics">View analytics <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /></Link></div><div className="mt-8 flex h-40 items-end gap-2 sm:gap-4">{[.42,.58,.48,.73,.64,.88,.69,.82,.75,.97,.65,.55].map((height, index) => <div key={index} className="group flex flex-1 flex-col items-center gap-2"><div className={`w-full rounded-t-lg transition-transform duration-300 group-hover:-translate-y-1 ${index === 9 ? 'bg-primary' : 'bg-secondary'}`} style={{ height: `${height * 100}%` }} /><span className="mono-font text-[10px] text-muted-foreground">{['N','D','J','F','M','A','M','J','J','A','S','O'][index]}</span></div>)}</div></section><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-sm text-muted-foreground">Where it goes</p><h2 className="display-font mt-1 text-2xl font-bold">Your top categories</h2></div><Link href="/budgets" className="text-sm font-semibold text-primary" data-testid="link-view-budgets">Budgets</Link></div><div className="mt-7 space-y-5">{data.categoryBreakdown.slice(0, 4).map((item) => <div key={item.category} data-testid={`row-category-${item.category}`}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{item.category}</span><span className="mono-font text-muted-foreground">{formatMoney(item.amount)}</span></div><div className="h-2 overflow-hidden rounded-full bg-secondary"><div className={`h-full rounded-full ${categoryColors[item.category] ?? 'bg-primary'}`} style={{ width: `${Math.min(item.percentage, 100)}%` }} /></div></div>)}</div></section></div><section className="mt-6 rounded-2xl border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-sm text-muted-foreground">Recent activity</p><h2 className="display-font mt-1 text-2xl font-bold">The latest moves</h2></div><Link href="/transactions" className="text-sm font-semibold text-primary" data-testid="link-view-transactions">See all <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /></Link></div><TransactionRows transactions={data.recentTransactions.slice(0, 5)} /></section></div>;
}

function TransactionRows({ transactions, onEdit, onDelete }: { transactions: Transaction[]; onEdit?: (transaction: Transaction) => void; onDelete?: (transaction: Transaction) => void }) {
  if (!transactions.length) return <div className="mt-6"><EmptyState icon={FileText} title="A blank page is a good start." body="Add your first expense or income and your money story will start to take shape." /></div>;
  return <div className="mt-5 divide-y divide-border">{transactions.map((transaction) => <div key={transaction.id} className="group flex items-center gap-3 py-4" data-testid={`row-transaction-${transaction.id}`}><div className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${transaction.type === 'income' ? 'bg-accent/50 text-primary' : 'bg-secondary text-foreground'}`}>{transaction.type === 'income' ? <ArrowDownLeft className="h-4 w-4" /> : <CreditCard className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{transaction.description || transaction.source || transaction.category}</p><p className="mt-0.5 text-xs text-muted-foreground">{transaction.category || transaction.source || 'Income'} · {formatDate(transaction.date)}</p></div><p className={`mono-font text-sm font-medium ${transaction.type === 'income' ? 'text-primary' : 'text-foreground'}`}>{transaction.type === 'income' ? '+' : '−'}{formatMoney(transaction.amount)}</p>{(onEdit || onDelete) && <div className="ml-2 flex gap-1 opacity-0 transition-opacity group-hover:opacity-100">{onEdit && <button onClick={() => onEdit(transaction)} className="rounded-lg p-2 text-muted-foreground hover:bg-secondary hover:text-foreground" data-testid={`button-edit-transaction-${transaction.id}`}><Edit3 className="h-3.5 w-3.5" /></button>}{onDelete && <button onClick={() => onDelete(transaction)} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" data-testid={`button-delete-transaction-${transaction.id}`}><Trash2 className="h-3.5 w-3.5" /></button>}</div>}</div>)}</div>;
}

type TransactionFormState = { type: 'expense' | 'income'; amount: string; date: string; category: string; source: string; paymentMethod: string; description: string };
const blankTransaction: TransactionFormState = { type: 'expense', amount: '', date: new Date().toISOString().slice(0, 10), category: categories[0], source: '', paymentMethod: 'Debit card', description: '' };
function TransactionDialog({ open, onOpenChange, editing, onSaved }: { open: boolean; onOpenChange: (open: boolean) => void; editing: Transaction | null; onSaved: () => void }) {
  const [form, setForm] = useState<TransactionFormState>(blankTransaction);
  const createExpense = useCreateExpense(); const updateExpense = useUpdateExpense(); const deleteExpense = useDeleteExpense();
  const createIncome = useCreateIncome(); const updateIncome = useUpdateIncome();
  useEffect(() => { if (open) setForm(editing ? { type: editing.type, amount: String(editing.amount), date: editing.date.slice(0, 10), category: editing.category || categories[0], source: editing.source || '', paymentMethod: editing.paymentMethod || 'Debit card', description: editing.description || '' } : blankTransaction); }, [editing, open]);
  const pending = createExpense.isPending || updateExpense.isPending || createIncome.isPending || updateIncome.isPending;
  const update = (key: keyof TransactionFormState, value: string) => setForm((prev) => ({ ...prev, [key]: value }));
  const save = () => {
    const expenseData = { amount: Number(form.amount), date: form.date, category: form.category, paymentMethod: form.paymentMethod, description: form.description };
    const incomeData = { amount: Number(form.amount), date: form.date, source: form.source, description: form.description };
    const done = () => { onOpenChange(false); onSaved(); };
    if (editing?.type === 'expense') updateExpense.mutate({ id: editing.id, data: expenseData }, { onSuccess: done }); else if (editing?.type === 'income') updateIncome.mutate({ id: editing.id, data: incomeData }, { onSuccess: done }); else if (form.type === 'expense') createExpense.mutate({ data: expenseData }, { onSuccess: done }); else createIncome.mutate({ data: incomeData }, { onSuccess: done });
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="rounded-3xl border-border bg-card sm:max-w-lg"><DialogHeader><DialogTitle className="display-font text-2xl">{editing ? 'Edit transaction' : 'Add a transaction'}</DialogTitle><DialogDescription>Keep it simple. You can always fill in more detail later.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid grid-cols-2 gap-2 rounded-xl bg-secondary p-1"><button className={`rounded-lg py-2 text-sm font-semibold ${form.type === 'expense' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} onClick={() => update('type', 'expense')} data-testid="button-type-expense">Expense</button><button className={`rounded-lg py-2 text-sm font-semibold ${form.type === 'income' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} onClick={() => update('type', 'income')} data-testid="button-type-income">Income</button></div><div className="grid grid-cols-2 gap-4"><div className="grid gap-2"><Label htmlFor="amount">Amount</Label><Input id="amount" type="number" min="0" step="0.01" placeholder="0.00" value={form.amount} onChange={(event) => update('amount', event.target.value)} data-testid="input-transaction-amount" /></div><div className="grid gap-2"><Label htmlFor="date">Date</Label><Input id="date" type="date" value={form.date} onChange={(event) => update('date', event.target.value)} data-testid="input-transaction-date" /></div></div>{form.type === 'expense' ? <div className="grid grid-cols-2 gap-4"><div className="grid gap-2"><Label htmlFor="category">Category</Label><select id="category" className="h-9 rounded-md border border-input bg-background px-3 text-sm" value={form.category} onChange={(event) => update('category', event.target.value)} data-testid="select-transaction-category">{categories.map((category) => <option key={category}>{category}</option>)}</select></div><div className="grid gap-2"><Label htmlFor="payment">Payment method</Label><Input id="payment" value={form.paymentMethod} onChange={(event) => update('paymentMethod', event.target.value)} data-testid="input-payment-method" /></div></div> : <div className="grid gap-2"><Label htmlFor="source">Income source</Label><Input id="source" placeholder="Part-time job, stipend..." value={form.source} onChange={(event) => update('source', event.target.value)} data-testid="input-income-source" /></div>}<div className="grid gap-2"><Label htmlFor="description">Note <span className="font-normal text-muted-foreground">(optional)</span></Label><Textarea id="description" placeholder="What was this for?" value={form.description} onChange={(event) => update('description', event.target.value)} data-testid="input-transaction-description" /></div></div><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)} data-testid="button-cancel-transaction">Cancel</Button><Button onClick={save} disabled={pending || !form.amount} data-testid="button-save-transaction">{pending ? 'Saving...' : editing ? 'Save changes' : 'Add transaction'}</Button></DialogFooter></DialogContent></Dialog>;
}

function TransactionsPage() {
  const [search, setSearch] = useState(''); const [type, setType] = useState(''); const [dialogOpen, setDialogOpen] = useState(false); const [editing, setEditing] = useState<Transaction | null>(null); const [deleting, setDeleting] = useState<Transaction | null>(null);
  const params = useMemo(() => ({ search: search || undefined, type: (type || undefined) as 'expense' | 'income' | undefined }), [search, type]);
  const query = useListTransactions(params, { query: { queryKey: getListTransactionsQueryKey(params) } }); const qc = useQueryClient();
  const deleteExpense = useDeleteExpense(); const deleteIncome = useDeleteIncome();
  const refresh = () => { qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); };
  const confirmDelete = () => { if (!deleting) return; const done = () => { setDeleting(null); refresh(); }; deleting.type === 'expense' ? deleteExpense.mutate({ id: deleting.id }, { onSuccess: done }) : deleteIncome.mutate({ id: deleting.id }, { onSuccess: done }); };
  return <div className="animate-rise-in"><PageTitle eyebrow="Your money trail" title="Transactions" body="A clear, searchable home for every move." action={<Button onClick={() => { setEditing(null); setDialogOpen(true); }} data-testid="button-add-transaction"><Plus className="h-4 w-4" /> Add transaction</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input className="bg-card pl-9" placeholder="Search transactions..." value={search} onChange={(event) => setSearch(event.target.value)} data-testid="input-search-transactions" /></div><div className="flex gap-2"><button onClick={() => setType('')} className={`rounded-xl border px-4 text-sm font-semibold ${!type ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card'}`} data-testid="button-filter-all">All</button><button onClick={() => setType('expense')} className={`rounded-xl border px-4 text-sm font-semibold ${type === 'expense' ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card'}`} data-testid="button-filter-expenses">Expenses</button><button onClick={() => setType('income')} className={`rounded-xl border px-4 text-sm font-semibold ${type === 'income' ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card'}`} data-testid="button-filter-income">Income</button></div></div>{query.isLoading ? <LoadingState label="Sorting your transactions..." /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : <section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center justify-between"><p className="text-sm font-semibold">{query.data?.length ?? 0} transactions</p><Filter className="h-4 w-4 text-muted-foreground" /></div>{query.data?.length ? <TransactionRows transactions={query.data} onEdit={(transaction) => { setEditing(transaction); setDialogOpen(true); }} onDelete={setDeleting} /> : <div className="mt-5"><EmptyState icon={Search} title="Nothing matches that search." body="Try a different word or clear your filters to see more." action={<Button variant="outline" onClick={() => { setSearch(''); setType(''); }} data-testid="button-clear-filters">Clear filters</Button>} /></div>}</section>}<TransactionDialog open={dialogOpen} onOpenChange={setDialogOpen} editing={editing} onSaved={refresh} /><Dialog open={!!deleting} onOpenChange={(open) => !open && setDeleting(null)}><DialogContent className="rounded-3xl border-border bg-card sm:max-w-md"><DialogHeader><DialogTitle className="display-font text-2xl">Delete this transaction?</DialogTitle><DialogDescription>This will remove {deleting?.description || deleting?.category || 'this entry'} from your money story. There’s no undo.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setDeleting(null)} data-testid="button-cancel-delete">Keep it</Button><Button variant="destructive" onClick={confirmDelete} disabled={deleteExpense.isPending || deleteIncome.isPending} data-testid="button-confirm-delete">Delete</Button></DialogFooter></DialogContent></Dialog></div>;
}

type BudgetForm = { name: string; amount: string; month: string; category: string };
function BudgetDialog({ open, onOpenChange, editing, onSaved }: { open: boolean; onOpenChange: (open: boolean) => void; editing: Budget | null; onSaved: () => void }) {
  const [form, setForm] = useState<BudgetForm>({ name: '', amount: '', month: new Date().toISOString().slice(0, 7), category: '' }); const create = useCreateBudget(); const update = useUpdateBudget();
  useEffect(() => { if (open) setForm(editing ? { name: editing.name, amount: String(editing.amount), month: editing.month, category: editing.category || '' } : { name: '', amount: '', month: new Date().toISOString().slice(0, 7), category: '' }); }, [editing, open]);
  const save = () => { const data = { name: form.name, amount: Number(form.amount), month: form.month, category: form.category || null }; const done = () => { onOpenChange(false); onSaved(); }; editing ? update.mutate({ id: editing.id, data }, { onSuccess: done }) : create.mutate({ data }, { onSuccess: done }); };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="rounded-3xl border-border bg-card sm:max-w-md"><DialogHeader><DialogTitle className="display-font text-2xl">{editing ? 'Edit budget' : 'Create a budget'}</DialogTitle><DialogDescription>Give your money a kind boundary, not a punishment.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid gap-2"><Label htmlFor="budget-name">Budget name</Label><Input id="budget-name" placeholder="Weekend food" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} data-testid="input-budget-name" /></div><div className="grid grid-cols-2 gap-4"><div className="grid gap-2"><Label htmlFor="budget-amount">Monthly amount</Label><Input id="budget-amount" type="number" min="0" step="0.01" placeholder="400" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })} data-testid="input-budget-amount" /></div><div className="grid gap-2"><Label htmlFor="budget-month">Month</Label><Input id="budget-month" type="month" value={form.month} onChange={(event) => setForm({ ...form, month: event.target.value })} data-testid="input-budget-month" /></div></div><div className="grid gap-2"><Label htmlFor="budget-category">Category <span className="font-normal text-muted-foreground">(optional)</span></Label><select id="budget-category" className="h-9 rounded-md border border-input bg-background px-3 text-sm" value={form.category} onChange={(event) => setForm({ ...form, category: event.target.value })} data-testid="select-budget-category"><option value="">Overall monthly budget</option>{categories.map((category) => <option key={category}>{category}</option>)}</select></div></div><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)} data-testid="button-cancel-budget">Cancel</Button><Button onClick={save} disabled={!form.name || !form.amount || create.isPending || update.isPending} data-testid="button-save-budget">{create.isPending || update.isPending ? 'Saving...' : 'Save budget'}</Button></DialogFooter></DialogContent></Dialog>;
}

function BudgetsPage() {
  const query = useListBudgets({ query: { queryKey: getListBudgetsQueryKey() } }); const qc = useQueryClient(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Budget | null>(null); const [deleting, setDeleting] = useState<Budget | null>(null); const remove = useDeleteBudget();
  const refresh = () => { qc.invalidateQueries({ queryKey: getListBudgetsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); };
  const months = useMemo(() => Array.from(new Set((query.data ?? []).map((budget) => budget.month))), [query.data]);
  return <div className="animate-rise-in"><PageTitle eyebrow="Gentle boundaries" title="Budgets" body="Plan for what matters, then let the rest of the month unfold." action={<Button onClick={() => { setEditing(null); setOpen(true); }} data-testid="button-add-budget"><Plus className="h-4 w-4" /> New budget</Button>} />{query.isLoading ? <LoadingState label="Measuring your breathing room..." /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : !query.data?.length ? <EmptyState icon={Target} title="Your first budget is a small act of care." body="Choose one category you want to feel more intentional about. You don't need to budget everything at once." action={<Button onClick={() => setOpen(true)} data-testid="button-empty-add-budget"><Plus className="h-4 w-4" /> Create a budget</Button>} /> : <div className="space-y-8">{months.map((month) => <section key={month}><div className="mb-4 flex items-center gap-3"><h2 className="display-font text-2xl font-bold">{monthName(month)}</h2><span className="rounded-full bg-secondary px-2.5 py-1 text-xs font-semibold text-muted-foreground">{query.data?.filter((budget) => budget.month === month).length} plans</span></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{query.data?.filter((budget) => budget.month === month).map((budget) => { const percentage = budget.amount ? (budget.spent / budget.amount) * 100 : 0; const over = budget.remaining < 0; return <div key={budget.id} className={`rounded-2xl border p-5 ${over ? 'border-destructive/35 bg-destructive/5' : 'border-border bg-card'}`} data-testid={`card-budget-${budget.id}`}><div className="flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.14em] text-muted-foreground">{budget.category || 'Overall'}</p><h3 className="display-font mt-1 text-xl font-bold">{budget.name}</h3></div><div className="flex gap-1"><button onClick={() => { setEditing(budget); setOpen(true); }} className="rounded-lg p-2 text-muted-foreground hover:bg-secondary" data-testid={`button-edit-budget-${budget.id}`}><Edit3 className="h-3.5 w-3.5" /></button><button onClick={() => setDeleting(budget)} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" data-testid={`button-delete-budget-${budget.id}`}><Trash2 className="h-3.5 w-3.5" /></button></div></div><div className="mt-7 flex items-end justify-between"><div><p className="mono-font text-2xl font-medium">{formatMoney(budget.spent)}</p><p className="mt-1 text-xs text-muted-foreground">of {formatMoney(budget.amount)} used</p></div><p className={`mono-font text-sm font-medium ${over ? 'text-destructive' : 'text-primary'}`}>{over ? `${formatMoney(Math.abs(budget.remaining))} over` : `${formatMoney(budget.remaining)} left`}</p></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-secondary"><div className={`h-full rounded-full ${over ? 'bg-destructive' : percentage > 80 ? 'bg-chart-3' : categoryColors[budget.category || ''] ?? 'bg-primary'}`} style={{ width: `${Math.min(percentage, 100)}%` }} /></div><p className="mt-3 text-xs text-muted-foreground">{Math.round(percentage)}% of your boundary used</p></div>})}</div></section>)}</div>}<BudgetDialog open={open} onOpenChange={setOpen} editing={editing} onSaved={refresh} /><Dialog open={!!deleting} onOpenChange={(openState) => !openState && setDeleting(null)}><DialogContent className="rounded-3xl border-border bg-card sm:max-w-md"><DialogHeader><DialogTitle className="display-font text-2xl">Remove this budget?</DialogTitle><DialogDescription>{deleting?.name} will disappear from your plans, but its transactions stay right where they are.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setDeleting(null)} data-testid="button-cancel-delete-budget">Keep it</Button><Button variant="destructive" onClick={() => deleting && remove.mutate({ id: deleting.id }, { onSuccess: () => { setDeleting(null); refresh(); } })} data-testid="button-confirm-delete-budget">Remove budget</Button></DialogFooter></DialogContent></Dialog></div>;
}

function AnalyticsPage() {
  const query = useGetAnalytics({ query: { queryKey: getGetAnalyticsQueryKey() } }); if (query.isLoading) return <LoadingState label="Finding the patterns in your spending..." />; if (query.isError) return <ErrorState retry={() => query.refetch()} />; const data = query.data; if (!data) return null; const max = Math.max(...data.monthly.map((item) => Math.max(item.income, item.expenses)), 1);
  return <div className="animate-rise-in"><PageTitle eyebrow="The bigger picture" title="Analytics" body="Patterns are helpful when they feel like information, not judgment." /><div className="grid gap-4 md:grid-cols-3"><StatCard label="Total saved" value={formatMoney(data.totalSavings)} detail="Across the time you’ve tracked" icon={Wallet} tone="dark" /><StatCard label="Average monthly spend" value={formatMoney(data.averageMonthlySpend)} detail="A useful baseline, not a limit" icon={BarChart3} /><StatCard label="Highest category" value={data.highestCategory} detail="Where most of your money goes" icon={PieChart} tone="accent" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="text-sm text-muted-foreground">Income vs expenses</p><h2 className="display-font mt-1 text-2xl font-bold">Your monthly rhythm</h2></div><div className="flex gap-4 text-xs text-muted-foreground"><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full bg-primary" />Income</span><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full bg-accent" />Expenses</span></div></div><div className="mt-8 flex h-56 items-end gap-3 sm:gap-5">{data.monthly.map((item) => <div className="group flex flex-1 items-end justify-center gap-1.5" key={item.month} title={`${item.month}: ${formatMoney(item.income)} income, ${formatMoney(item.expenses)} expenses`}><div className="w-1/2 rounded-t-md bg-primary transition-transform group-hover:-translate-y-1" style={{ height: `${Math.max((item.income / max) * 100, 4)}%` }} /><div className="w-1/2 rounded-t-md bg-accent transition-transform group-hover:-translate-y-1" style={{ height: `${Math.max((item.expenses / max) * 100, 4)}%` }} /></div>)}</div><div className="mt-3 flex gap-3 sm:gap-5">{data.monthly.map((item) => <span key={item.month} className="mono-font flex-1 text-center text-[10px] text-muted-foreground">{item.month.slice(5)}</span>)}</div></section><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><p className="text-sm text-muted-foreground">Category breakdown</p><h2 className="display-font mt-1 text-2xl font-bold">Your spending shape</h2><div className="mt-7 space-y-4">{data.categories.slice(0, 6).map((item) => <div key={item.category}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{item.category}</span><span className="mono-font text-muted-foreground">{item.percentage.toFixed(1)}%</span></div><div className="h-2 rounded-full bg-secondary"><div className={`h-full rounded-full ${categoryColors[item.category] ?? 'bg-primary'}`} style={{ width: `${item.percentage}%` }} /></div><p className="mt-1 text-xs text-muted-foreground">{formatMoney(item.amount)}</p></div>)}</div></section></div></div>;
}

function AdvisorPage() {
  const ask = useAskAdvisor(); const [question, setQuestion] = useState(''); const [answer, setAnswer] = useState<{ answer: string; highlights: string[] } | null>(null); const suggestions = ['Can I afford a weekend away?', 'Where could I trim without feeling deprived?', 'Am I saving enough right now?'];
  const submit = (value = question) => { if (!value.trim()) return; setQuestion(value); ask.mutate({ data: { question: value } }, { onSuccess: setAnswer }); };
  return <div className="mx-auto max-w-4xl animate-rise-in"><div className="text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-accent text-accent-foreground"><Sparkles className="h-6 w-6" /></div><p className="mono-font mt-5 text-xs uppercase tracking-[.18em] text-primary">A second set of eyes</p><h1 className="display-font mt-3 text-4xl font-bold tracking-tight sm:text-5xl">Ask your money advisor.</h1><p className="mx-auto mt-4 max-w-xl leading-7 text-muted-foreground">No spreadsheets. No shame. Ask a plain-language question and get a thoughtful answer from the shape of your spending.</p></div><div className="mx-auto mt-10 max-w-2xl rounded-3xl border border-border bg-card p-3 shadow-xl shadow-primary/5"><div className="flex items-end gap-2"><Textarea className="min-h-[100px] resize-none border-0 bg-transparent shadow-none focus-visible:ring-0" placeholder="Try “Can I spend $80 on dinner tonight?”" value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); submit(); } }} data-testid="input-advisor-question" /><Button onClick={() => submit()} disabled={ask.isPending || !question.trim()} className="mb-1 shrink-0 rounded-xl" data-testid="button-ask-advisor">{ask.isPending ? 'Thinking...' : 'Ask'} <ArrowUpRight className="h-4 w-4" /></Button></div></div><div className="mx-auto mt-5 flex max-w-2xl flex-wrap justify-center gap-2">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => submit(suggestion)} className="rounded-full border border-border bg-card px-3.5 py-2 text-xs font-semibold text-muted-foreground hover:border-primary hover:text-primary" data-testid={`button-suggestion-${suggestion.slice(0, 8).replaceAll(' ', '-')}`}>{suggestion}</button>)}</div>{answer ? <section className="mx-auto mt-10 max-w-2xl rounded-3xl border border-primary/20 bg-primary/5 p-6 sm:p-8"><div className="flex items-center gap-2 text-sm font-semibold text-primary"><Sparkles className="h-4 w-4" /> A thought for you</div><p className="mt-5 text-lg leading-8">{answer.answer}</p><div className="mt-7 grid gap-3">{answer.highlights.map((highlight) => <div key={highlight} className="flex gap-3 rounded-xl bg-card p-3 text-sm"><span className="mt-0.5 h-2 w-2 shrink-0 rounded-full bg-accent-foreground" />{highlight}</div>)}</div></section> : <div className="mx-auto mt-12 max-w-2xl"><p className="text-center text-xs font-bold uppercase tracking-[.18em] text-muted-foreground">Good questions to start with</p><div className="mt-4 grid gap-3 sm:grid-cols-3">{suggestions.map((suggestion, index) => <button key={suggestion} onClick={() => submit(suggestion)} className="rounded-2xl border border-border bg-card p-4 text-left text-sm font-semibold hover:-translate-y-0.5 hover:border-primary" data-testid={`card-question-${index}`}><span className="mono-font text-xs text-primary">0{index + 1}</span><span className="mt-7 block leading-5">{suggestion}</span></button>)}</div></div>}</div>;
}

function SettingsPage() {
  const user = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey() } }); const { signOut } = useClerk(); const [dark, setDark] = useState(() => localStorage.getItem('pocketwise-theme') === 'dark');
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('pocketwise-theme', dark ? 'dark' : 'light'); }, [dark]);
  return <div className="animate-rise-in max-w-3xl"><PageTitle eyebrow="Your space" title="Settings" body="A few quiet controls for making pocketwise feel like yours." /><section className="rounded-2xl border border-border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-muted-foreground">Account</p><div className="mt-5 flex items-center gap-4"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-accent text-lg font-bold text-accent-foreground">{user.data?.initials || 'MP'}</div><div><h2 className="display-font text-xl font-bold" data-testid="text-account-name">{user.data?.name || 'Your account'}</h2><p className="text-sm text-muted-foreground" data-testid="text-account-email">{user.data?.email || 'Signed in account'}</p></div></div></section><section className="mt-5 rounded-2xl border border-border bg-card p-6"><p className="text-xs font-bold uppercase tracking-[.16em] text-muted-foreground">Preferences</p><div className="mt-5 flex items-center justify-between border-b border-border pb-5"><div><p className="font-semibold">Appearance</p><p className="mt-1 text-sm text-muted-foreground">Choose a brighter or deeper money space.</p></div><button onClick={() => setDark(!dark)} className={`relative h-7 w-12 rounded-full p-1 ${dark ? 'bg-primary' : 'bg-secondary'}`} data-testid="button-toggle-theme"><span className={`block h-5 w-5 rounded-full bg-card shadow-sm transition-transform ${dark ? 'translate-x-5' : ''}`} /></button></div><div className="flex items-center justify-between pt-5"><div><p className="font-semibold">Weekly check-in</p><p className="mt-1 text-sm text-muted-foreground">A gentle reminder to look at your rhythm.</p></div><span className="rounded-full bg-accent/50 px-3 py-1 text-xs font-bold text-accent-foreground">Coming soon</span></div></section><section className="mt-5 flex flex-col gap-3 rounded-2xl border border-destructive/20 bg-destructive/5 p-6 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">Ready to step away?</p><p className="mt-1 text-sm text-muted-foreground">You can come back whenever your money needs you.</p></div><Button variant="outline" onClick={() => signOut({ redirectUrl: basePath || '/' })} data-testid="button-settings-sign-out"><LogOut className="h-4 w-4" /> Sign out</Button></section></div>;
}

function SignInPage() { return <div className="grain flex min-h-[100dvh] items-center justify-center bg-background px-4 py-10"><SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} /></div>; }
function SignUpPage() { return <div className="grain flex min-h-[100dvh] items-center justify-center bg-background px-4 py-10"><SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} /></div>; }
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function HomeRedirect() { return <HomePage />; }
function AuthenticatedPage({ children }: { children: ReactNode }) { return <Protected>{children}</Protected>; }

function ClerkRoutes() {
  const [, setLocation] = useLocation();
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{ signIn: { start: { title: 'Welcome back', subtitle: 'A clearer money space is waiting.' } }, signUp: { start: { title: 'Start your money story', subtitle: 'A little clarity goes a long way.' } } }} routerPush={(to) => setLocation(to.replace(basePath, '') || '/')} routerReplace={(to) => setLocation(to.replace(basePath, '') || '/')}><QueryClientProvider client={queryClient}><Switch><Route path="/" component={HomeRedirect} /><Route path="/sign-in/*?" component={SignInPage} /><Route path="/sign-up/*?" component={SignUpPage} /><Route path="/dashboard"><AuthenticatedPage><DashboardPage /></AuthenticatedPage></Route><Route path="/transactions"><AuthenticatedPage><TransactionsPage /></AuthenticatedPage></Route><Route path="/budgets"><AuthenticatedPage><BudgetsPage /></AuthenticatedPage></Route><Route path="/analytics"><AuthenticatedPage><AnalyticsPage /></AuthenticatedPage></Route><Route path="/advisor"><AuthenticatedPage><AdvisorPage /></AuthenticatedPage></Route><Route path="/settings"><AuthenticatedPage><SettingsPage /></AuthenticatedPage></Route><Route component={NotFound} /></Switch></QueryClientProvider></ClerkProvider>;
}

function App() {
  return <TooltipProvider><WouterRouter base={basePath}><RoutedErrorBoundary><ClerkRoutes /></RoutedErrorBoundary></WouterRouter><Toaster /></TooltipProvider>;
}

export default App;